/// \file
/// This file implements the targeting of the RegisterBankInfo class for
/// MMIX.
/// \todo This should be generated by TableGen.
//===----------------------------------------------------------------------===//

#include "MMIXRegisterBankInfo.h"
#include "MCTargetDesc/MMIXMCTargetDesc.h"
#include "MMIXRegisterInfo.h"

#define GET_TARGET_REGBANK_IMPL
#include "MMIXGenRegisterBankInfo.inc"

namespace llvm::MMIX {

enum PartialMappingIdx {
  PMI_None = -1,
  PMI_GPRBank64,
};

enum ValueMappingIdx {
  InvalidIdx = 0,
  GenericMappingIdx = 1,
  GConstantMappingIdx = 3,
};

const RegisterBankInfo::PartialMapping PartMappings[] = {
    /* StartIdx, Length, RegBank */
    // 0: GPR 64-bit value.
    {0, 64, MMIX::GPRBank},
};

const RegisterBankInfo::ValueMapping ValMappings[] = {
    /* BreakDown, NumBreakDowns */
    // 0: invalid
    {nullptr, 0},
    {&PartMappings[PMI_GPRBank64], 1},
    {&PartMappings[PMI_GPRBank64], 1},
    {&PartMappings[PMI_GPRBank64], 1},
    {nullptr, 0},
};

} // namespace llvm::MMIX

using namespace llvm;

const MMIXRegisterBankInfo::InstructionMapping &
MMIXRegisterBankInfo::getInstrMapping(const MachineInstr &MI) const {
  const unsigned Opc = MI.getOpcode();
  // Try the default logic for non-generic instructions that are either copies
  // or already have some operands assigned to banks.
  if (!isPreISelGenericOpcode(Opc) || Opc == TargetOpcode::G_PHI) {
    const RegisterBankInfo::InstructionMapping &Mapping =
        getInstrMappingImpl(MI);
    if (Mapping.isValid())
      return Mapping;
  }

  switch (Opc) {
  case TargetOpcode::G_CONSTANT:
  case TargetOpcode::G_FCONSTANT:
    return getInstructionMapping(DefaultMappingID, /*Cost*/ 1,
                                 &MMIX::ValMappings[MMIX::GConstantMappingIdx],
                                 2);
  default:
    break;
  }

  unsigned NumOperands = MI.getNumOperands();
  return getInstructionMapping(DefaultMappingID, /*Cost*/ 1,
                               &MMIX::ValMappings[MMIX::GenericMappingIdx],
                               NumOperands);
}
